import numpy as np
from IQEngine.interface import AbstractPosition
from IQEngine.core import BaseObject
from IQEngine.core.engine import Engine
from IQCommon.exception import get_traceback_message
from IQCommon.logger import system_log
class Positions(dict):
    def __init__(self, position_cls):
        super(Positions, self).__init__()
        self._position_cls = position_cls
        self._cached_positions = {}
    def __missing__(self, key):
        if (key not in self._cached_positions):
            try:
                self._cached_positions[key] = self._position_cls(key)
            except Exception:
                system_log.error(get_traceback_message())
                return None
        return self._cached_positions[key]
    def get_or_create(self, key):
        if (key not in self):
            self[key] = self._position_cls(key)
        return self[key]
    return (__classcell__ := __class__)
class BasePosition(AbstractPosition, BaseObject):
    def __init__(self, symbol):
        self._asset = Engine.instance().get_asset(symbol)
        self._last_price = float('NaN')
    @property
    def symbol(self):
        return self._asset.symbol
    @property
    def asset(self):
        return self._asset
    @property
    def position_type(self):
        raise NotImplementedError
    @property
    def type(self):
        raise NotImplementedError
    @property
    def market_value(self):
        raise NotImplementedError
    @property
    def transaction_cost(self):
        raise NotImplementedError
    @property
    def last_price(self):
        if np(self._last_price if np.isnan(self._last_price) else Engine.instance().get_last_price(self.symbol)):
            pass
    def update_last_price(self):
        price = Engine.instance().get_last_price(self.symbol)
        if (not np.isnan(price)):
            if price:
                self._last_price = price
                return None
            return None
    def is_de_listed(self):
        raise NotImplementedError
    def make_settlement(self):
        raise NotImplementedError
    def make_trade(self, trade):
        raise NotImplementedError
    @property
    def _repr_attr_list(self):
        raise NotImplementedError
